function json(filePath)
    local configDir = getWorkingDirectory() .. '\\config'

    filePath = configDir .. '\\' .. (filePath:match('%.json$') and filePath or filePath .. '.json')

    local class = {}

    if not doesDirectoryExist(configDir) then
        createDirectory(configDir)
    end

    function class:Save(tbl)
        tbl = tbl or {}
        local file = io.open(filePath, 'w')
        if not file then
            return false, 'Не удалось открыть файл для записи'
        end
        local encoded = encodeJson(tbl)
        if not encoded then
            file:close()
            return false, 'Ошибка кодирования JSON'
        end
        file:write(encoded)
        file:close()

        return true, 'ok'
    end

    function class:Load(defaultTable)
        defaultTable = defaultTable or {}

        if not doesFileExist(filePath) then
            self:Save(defaultTable)
            return defaultTable
        end

        local file = io.open(filePath, 'r')
        if not file then
            return defaultTable
        end

        local content = file:read('*a')
        file:close()

        local data = {}

        if content and content ~= '' then
            local ok, result = pcall(decodeJson, content)

            if ok and type(result) == 'table' then
                data = result
            else
                print('[JSON] Ошибка чтения файла: ' .. tostring(filePath))
                print('[JSON] Файл будет восстановлен.')

                data = defaultTable
                self:Save(data)
                return data
            end
        else
            data = defaultTable
            self:Save(data)
            return data
        end

        -- Рекурсивное добавление отсутствующих полей
        local function merge(dataTbl, defaultTbl)
            for k, v in pairs(defaultTbl) do
                if dataTbl[k] == nil then
                    if type(v) == 'table' then
                        dataTbl[k] = {}
                        merge(dataTbl[k], v)
                    else
                        dataTbl[k] = v
                    end
                elseif type(v) == 'table' and type(dataTbl[k]) == 'table' then
                    merge(dataTbl[k], v)
                end
            end
        end

        merge(data, defaultTable)

        -- Автоматически обновляем JSON новыми полями
        self:Save(data)

        return data
    end

    return class
end
