local function message(text, color)
    if not text or text == '' then return end
    if not color or color == '' then color = base_color end
    if smile then
        sampAddChatMessage(smile .. ' ' .. tag .. ' ' .. text, color)
    else
        sampAddChatMessage(tag .. ' ' .. text, color)
    end
end
local function test_message(text, color)
    if not settings.debugmessage then return end

    if not text or text == ' ' then return end
    if not color or color == ' ' then color = base_color end

    if smile then
        sampAddChatMessage(smile .. ' {ff0000}[DEBUG MESSAGE] ' .. tag .. ' ' .. text, color)
    else
        sampAddChatMessage('{ff0000}[DEBUG MESSAGE] ' .. tag .. ' ' .. text, color)
    end
end

Inventory = Inventory or {}

local function updateInventory(str)

    local ok, data = pcall(cjson.decode, str)
    if not ok then
        print("Ошибка JSON: " .. tostring(data))
        return
    end

    for _, page in ipairs(data) do
        if page.data and page.data.items then

            local invType = page.data.type
            Inventory[invType] = Inventory[invType] or {
                slots = {},
                maxSlot = 0
            }

            local inv = Inventory[invType]
            for _, item in ipairs(page.data.items) do

                local slot = item.slot
                -- если это предмет, обновляем слот
                if item.item then

                    inv.slots[slot] = item

                    if slot > inv.maxSlot then
                        inv.maxSlot = slot
                    end

                else
                    -- если пришел пустой слот - очищаем его
                    inv.slots[slot] = nil
                end

            end
        end
    end
end

