local renderWindow = imgui.new.bool(false)
imgui.OnInitialize(function()
    imgui.GetIO().IniFilename = nil
    proklyatiyTalon = imgui.CreateTextureFromFileInMemory(imgui.new('const char*', proklyat), #proklyat)
    talonTrade = imgui.CreateTextureFromFileInMemory(imgui.new('const char*', talon12hTrade), #talon12hTrade)
    talon8H = imgui.CreateTextureFromFileInMemory(imgui.new('const char*', talon8h), #talon8h)
    talonNotTrade = imgui.CreateTextureFromFileInMemory(imgui.new('const char*', talon12hNotTrade), #talon12hNotTrade)
    talon24H = imgui.CreateTextureFromFileInMemory(imgui.new('const char*', talon24h), #talon24h)
    theme()
    local config = imgui.ImFontConfig()
    config.MergeMode = true
    config.PixelSnapH = true
    iconRanges = imgui.new.ImWchar[3](faicons.min_range, faicons.max_range, 0)
    imgui.GetIO().Fonts:AddFontFromMemoryCompressedBase85TTF(faicons.get_font_data_base85('solid'), 14, config, iconRanges)
end)

local newFrame = imgui.OnFrame(
function() return renderWindow[0] end,
function(player)
    local resX, resY = getScreenResolution()
    local sizeX, sizeY = 450, 650
    imgui.SetNextWindowPos(imgui.ImVec2(resX / 2, resY / 2), imgui.Cond.FirstUseEver, imgui.ImVec2(0.5, 0.5))
    imgui.SetNextWindowSize(imgui.ImVec2(sizeX, sizeY), imgui.Cond.FirstUseEver)

    if imgui.Begin('AutoUse X4', renderWindow, imgui.WindowFlags.NoResize + imgui.WindowFlags.NoCollapse) then
        imgui.SetWindowFontScale(1.15)
        imgui.TextColored(imgui.ImVec4(0.35, 0.85, 1.0, 1.0), faicons('ticket') .. u8' Автоиспользование X4')
        imgui.SetWindowFontScale(1.0)

        imgui.Separator()
        imgui.Spacing()

        if imgui.Checkbox(faicons('bolt') .. u8' Автоиспользование талона', AUX4) then
            settings.CheckX4 = AUX4[0]
            save_settings()
        end
        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(faicons('circle_info') .. u8' Когда закончится X4,')
            imgui.Text(u8'автоматически активируется выбранный талон.')
            imgui.EndTooltip()
        end

        imgui.Spacing()

        if imgui.Checkbox(faicons('shuffle') .. u8' Использовать другой талон', UseFallbackX4) then
            settings.UseFallbackX4 = UseFallbackX4[0]
            save_settings()
        end
        if imgui.IsItemHovered() then
            imgui.BeginTooltip()
            imgui.Text(faicons('circle_info') .. u8' Если основной талон отсутствует,')
            imgui.Text(u8'будет выбран другой талон, который есть в инвентаре.')
            imgui.EndTooltip()
        end

        imgui.Spacing()

        if imgui.Checkbox(faicons('bug') .. u8' DEBUG сообщения', debugmessage) then
            settings.debugmessage = debugmessage[0]
            save_settings()
        end

        imgui.Spacing()
        imgui.Separator()

        local talons = {

            {
                key = 'ProklyatiyX4',
                name = 'Проклятый талон\nна 18 часов',

                useVar = ProklyatiyX4,
                image = proklyatiyTalon
            },

            {
                key = 'BaseX4',
                name = 'Талон на 12 часов\n(передаваемый)',

                useVar = BaseX4,
                image = talonTrade
            },

            {
                key = 'x4for8hours',
                name = 'Талон на 8 часов',

                useVar = X4for8Hours,
                image = talon8H
            },

            {
                key = 'X4for12HoursNotTransferable',
                name = 'Талон на 12 часов\n(непередаваемый)',

                useVar = X4for12HoursNotTransferable,
                image = talonNotTrade
            },

            {
                key = 'x4for24hours',
                name = 'Талон на 24 часа\n(непередаваемый)',

                useVar = X4for24Hours,
                image = talon24H
            }
        }

        for i, talon in ipairs(talons) do
            if i % 2 == 1 then
                if i > 1 then
                    imgui.NewLine()
                end
            else
                imgui.SameLine()
            end

            local talonSettings = settings[talon.key]
            if not talonSettings then
                talonSettings = {
                    slot = -1,
                    amount = -1,
                    use = false
                }
                settings[talon.key] = talonSettings
                save_settings()
            end

            local slot = tonumber(talonSettings.slot) or -1
            local amount = tonumber(talonSettings.amount) or 0
            local selected = talonSettings.use == true

            imgui.BeginChild('##Talon_' .. talon.key, imgui.ImVec2(210, 280), true)

            if selected then
                imgui.TextColored(imgui.ImVec4(0.4, 1.0, 0.5, 1.0), faicons('circle_check') .. u8' Основной талон')
            else
                imgui.TextColored(imgui.ImVec4(0.55, 0.55, 0.55, 1.0), faicons('circle') .. u8' Не выбран')
            end

            imgui.Separator()
            imgui.Text(faicons('ticket') .. u8(' ' .. talon.name))
            imgui.Spacing()


            imgui.TextColored(imgui.ImVec4(0.65, 0.75, 0.85, 1.0), faicons('box') .. u8' Слот: ' .. (slot >= 0 and tostring(slot) or '—'))

            imgui.TextColored(
                amount > 0
                and imgui.ImVec4(0.4, 1.0, 0.5, 1.0)
                or imgui.ImVec4(1.0, 0.4, 0.4, 1.0),

                faicons('cubes') .. u8' Количество: ' .. tostring(amount))

            if amount > 0 then
                imgui.TextColored(imgui.ImVec4(0.4, 1.0, 0.5, 1.0), faicons('circle_check') .. u8' В наличии')
            else
                imgui.TextColored(imgui.ImVec4(1.0, 0.4, 0.4, 1.0), faicons('circle_xmark') .. u8' Нет в инвентаре' )
            end

            imgui.Spacing()

            if imgui.Button(faicons('bolt') .. u8' Использовать##' .. talon.key, imgui.ImVec2(190, 28)) then
                UseTalon(talon.key)
            end

            imgui.Spacing()

            if imgui.Checkbox(faicons('star') .. u8' Использовать его##' .. talon.key, talon.useVar) then
                if talon.useVar[0] then
                    for _, otherTalon in ipairs(talons) do
                        local otherSettings = settings[otherTalon.key]
                        if otherSettings then
                            if otherTalon.key == talon.key then
                                otherSettings.use = true
                                otherTalon.useVar[0] = true
                            else
                                otherSettings.use = false
                                otherTalon.useVar[0] = false
                            end
                        end
                    end
                    message('Основной талон: ' .. talon.name:gsub('\n', ' '))
                else
                    talonSettings.use = false
                end
                save_settings()
            end

            imgui.Spacing()

            if talon.image then
                imgui.Image(talon.image, imgui.ImVec2(80, 80))
            end

            imgui.EndChild()
        end

        imgui.Spacing()
        imgui.Separator()
        imgui.Spacing()

        imgui.SetWindowFontScale(1.05)
        imgui.TextColored(imgui.ImVec4(0.45, 0.85, 1.0, 1.0), faicons('circle_info') .. u8' Выбор основного талона')
        imgui.SetWindowFontScale(1.0)

        if settings.UseFallbackX4 then
            imgui.TextColored(imgui.ImVec4(0.4, 1.0, 0.5, 1.0), faicons('shuffle') .. u8' Запасной талон включён')
        else
            imgui.TextColored(imgui.ImVec4(1.0, 0.6, 0.3, 1.0), faicons('lock') .. u8' Запасной талон отключён')
        end

        imgui.End()
    end
end)

local function updateTalonsFromInventory()
    local items = {
        {
            key = "ProklyatiyX4",
            item = 8948,
            text = "Проклятый Х4"
        },
        {
            key = "BaseX4",
            item = 7351,
            text = "Базовый Х4"
        },
        {
            key = "x4for8hours",
            item = 7781,
            text = "8-ми часовой Х4"
        },
        {
            key = "X4for12HoursNotTransferable",
            item = 8290,
            text = "Непередаваемый 12-ти часовой Х4"
        },
        {
            key = "x4for24hours",
            item = 7782,
            text = "24-ёх часовой Х4"
        },
    }

    local inventory = Inventory[1]
    if not inventory or not inventory.slots then return end
    local needSave = false

    for _, v in ipairs(items) do
        local foundSlot = -1
        local foundAmount = -1

        for slot, itemData in pairs(inventory.slots) do
            if itemData
            and tonumber(itemData.item) == tonumber(v.item) then

                foundSlot = tonumber(slot) or -1
                foundAmount = tonumber(itemData.amount) or 0
                break
            end
        end

        settings[v.key] = settings[v.key] or {
            slot = -1,
            amount = -1,
            use = false
        }

        local talonSettings = settings[v.key]
        if foundSlot >= 0 then

            if talonSettings.slot ~= foundSlot
            or talonSettings.amount ~= foundAmount then

                talonSettings.slot = foundSlot
                talonSettings.amount = foundAmount

                test_message(
                    v.text ..
                    ' | Слот: ' .. foundSlot ..
                    ' | Кол-во: ' .. foundAmount
                )

                needSave = true
            end

        else
            -- Талон не найден
            test_message(v.text .. ' | Талон не найден в инвентаре')

            -- Меняем настройки только при необходимости
            if talonSettings.slot ~= -1
            or talonSettings.amount ~= -1 then

                talonSettings.slot = -1
                talonSettings.amount = -1
                needSave = true
            end
        end
    end

    if needSave then
        needSave = false
        save_settings()
    end
end

