function ev.onServerMessage(color, text)
    --Вы получили — X4 PayDay %(осталось 0 PayDay%)
	if text:match('Вы получили — X4 PayDay %(осталось 0 PayDay%)') then
        if settings.CheckX4 then
            for i, talon in ipairs(AutoUseTalons) do
                if settings[talon.key].use then
                    message("x4 ПейДей закончился, использую новый!")
                    UseTalon(talon.key)
                    break
                end
            end
        end
    end

    if text:match('%[Ошибка%] %{ffffff%}Дождитесь завершения предыдущей активации талона!') then
        return
    end
end

function UseTalon(talonKey)

    local talons = {
        {
            key = 'ProklyatiyX4',
            name = 'Проклятый талон на 18 часов'
        },
        {
            key = 'BaseX4',
            name = 'Талон на 12 часов (передаваемый)'
        },
        {
            key = 'x4for8hours',
            name = 'Талон на 8 часов'
        },
        {
            key = 'X4for12HoursNotTransferable',
            name = 'Талон на 12 часов (непередаваемый)'
        },
        {
            key = 'x4for24hours',
            name = 'Талон на 24 часа (непередаваемый)'
        },
    }

    local talonConfig = nil
    for _, talon in ipairs(talons) do
        if talon.key == talonKey then
            talonConfig = talon
            break
        end
    end

    if not talonConfig then
        message('Ошибка: талон ' .. tostring(talonKey) .. ' не найден!')
        return false
    end

    local talonSettings = settings[talonKey]
    if not talonSettings then
        message('Ошибка: настройки талона не найдены!')
        return false
    end

    local slot = tonumber(talonSettings.slot)
    local amount = tonumber(talonSettings.amount) or 0

    if amount < 2 and settings.UseFallbackX4 then
        for _, otherTalon in ipairs(talons) do
            if otherTalon.key ~= talonKey then
                local otherSettings = settings[otherTalon.key]

                if otherSettings then
                    local otherSlot = tonumber(otherSettings.slot)
                    local otherAmount = tonumber(otherSettings.amount) or 0

                    if otherSlot
                    and otherSlot >= 0
                    and otherAmount > 0 then

                        message('Талона "' .. talonConfig.name .. '" осталось: ' ..  amount .. '. Использую другой: ' .. otherTalon.name)

                        talonConfig = otherTalon
                        talonSettings = otherSettings

                        slot = otherSlot
                        amount = otherAmount

                        break
                    end
                end
            end
        end
    end

    if not slot or slot < 0 or amount <= 0 then
        message('Талон "' .. talonConfig.name .. '" недоступен или отсутствует в инвентаре.')
        return false
    end

    emul_num({220, 0, 27, 64})
    sampSendChat('/invent')
    sendCEF('clickOnButton|{"type": 1,"slot": ' .. slot .. ', "action": 1}')

    sendCEF('inventoryClose')
    message('Использован талон: ' .. talonConfig.name .. ' | Осталось: ' .. amount)

    return true
end

addEventHandler('onReceivePacket', function (id, bs)
    if id == 220 then
        raknetBitStreamIgnoreBits(bs, 8)
        if (raknetBitStreamReadInt8(bs) == 17) then
            raknetBitStreamIgnoreBits(bs, 32)
            local length = raknetBitStreamReadInt16(bs)
            local encoded = raknetBitStreamReadInt8(bs)
            local str = (encoded ~= 0) and raknetBitStreamDecodeString(bs, length + encoded) or raknetBitStreamReadString(bs, length)

            if str:match('event.inventory.playerInventory') then
                local json = str:match("`(.-)`")
                if json then updateInventory(json) updateTalonsFromInventory() end
            end

        end
    end
end)

sendCEF = function(str)
    local bs = raknetNewBitStream()
    raknetBitStreamWriteInt8(bs, 220)
    raknetBitStreamWriteInt8(bs, 18)
    raknetBitStreamWriteInt16(bs, #str)
    raknetBitStreamWriteString(bs, str)
    raknetBitStreamWriteInt32(bs, 0)
    raknetSendBitStream(bs)
    raknetDeleteBitStream(bs)
end

function emul_num(array)
    local bs = raknetNewBitStream()
    for i, byte in ipairs(array) do
        raknetBitStreamWriteInt8(bs, byte)
    end
    raknetSendBitStream(bs)
    raknetDeleteBitStream(bs)
end

